query getTrend($filter: Filter) {
  trend(filter: $filter) {
    dexTrend {
      ...ScoreTrendNodeCommon
    }
    technologyTrend {
      ...ScoreTrendNodeCommon
    }
    sentimentTrend {
      ...ScoreTrendNodeCommon
    }
  }
}


fragment ScoreTrendNodeCommon on TrendNodeScore {
  startDate
  endDate
  value
  userCount
}
